   496	func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
   497		transcript := opts.Transcript
   498	
   499		// TranscriptPath fallback: data read from disk is an untrusted source,
   500		// so we redact it here. The in-memory path (opts.Transcript) is already
   501		// pre-redacted by the caller.
   502		if transcript.Len() == 0 && opts.TranscriptPath != "" {
   503			rawData, readErr := os.ReadFile(opts.TranscriptPath)
   504			if readErr != nil {
   505				rawData = nil
   506			}
   507			if len(rawData) > 0 {
   508				redacted, redactErr := redact.JSONLBytes(rawData)
   509				if redactErr != nil {
   510					return fmt.Errorf("failed to redact transcript from file: %w", redactErr)
   511				}
