   436	// readTranscriptFromObjectTree reads and reassembles a transcript from a git tree object.
   437	// Handles both chunked and non-chunked transcripts. Uses agent-aware reassembly
   438	// when agentType is known, falling back to JSONL reassembly otherwise.
   439	func readTranscriptFromObjectTree(tree *object.Tree, agentType types.AgentType) ([]byte, error) {
   440		var chunkFiles []string
   441		var hasBaseFile bool
   442	
   443		for _, entry := range tree.Entries {
   444			if entry.Name == paths.V2RawTranscriptFileName {
   445				hasBaseFile = true
   446			}
   447			if strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
   448				idx := agent.ParseChunkIndex(entry.Name, paths.V2RawTranscriptFileName)
   449				if idx > 0 {
   450					chunkFiles = append(chunkFiles, entry.Name)
   451				}
   452			}
   453		}
   454	
   455		// If chunk files exist, reassemble all chunks (base file is chunk 0)
   456		if len(chunkFiles) > 0 {
   457			chunkFiles = agent.SortChunkFiles(chunkFiles, paths.V2RawTranscriptFileName)
   458			if hasBaseFile {
   459				chunkFiles = append([]string{paths.V2RawTranscriptFileName}, chunkFiles...)
   460			}
   461	
   462			var chunks [][]byte
   463			for _, chunkFile := range chunkFiles {
   464				file, fileErr := tree.File(chunkFile)
   465				if fileErr != nil {
   466					continue
   467				}
   468				content, contentErr := file.Contents()
   469				if contentErr != nil {
   470					continue
   471				}
   472				chunks = append(chunks, []byte(content))
   473			}
   474	
   475			if len(chunks) > 0 {
   476				result, reassembleErr := agent.ReassembleTranscript(chunks, agentType)
   477				if reassembleErr != nil {
   478					return nil, fmt.Errorf("failed to reassemble transcript: %w", reassembleErr)
   479				}
   480				return result, nil
   481			}
   482		}
   483	
   484		// No chunk files — read base file directly (non-chunked transcript)
   485		if hasBaseFile {
   486			file, err := tree.File(paths.V2RawTranscriptFileName)
   487			if err == nil {
   488				content, contentErr := file.Contents()
   489				if contentErr == nil {
   490					return []byte(content), nil
   491				}
   492			}
   493		}
   494	
   495		return nil, nil
   496	}
